{% doc %}
  Fulldev UI section styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-section.css' | asset_url | stylesheet_tag }}

[data-slot='section'] {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--section-gap);
  padding-block: var(--section-padding);
  background: var(--background);
  color: var(--foreground);
  scroll-margin-top: 48px;
}
[data-slot='section'][data-variant='bordered'] {
  padding-block: 32px;
  border-block: 1px solid var(--border);
}
/* The first section of a template page, below the header. */
[data-slot='section'][data-variant='page'] {
  padding-top: 32px;
}
/* A framed panel inset by the gutter, as Fulldev UI's floating section. */
[data-slot='section'][data-variant='floating'] {
  width: calc(100% - 2 * var(--gutter));
  max-width: calc(var(--container) - 2 * var(--gutter));
  margin: 64px auto;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
}
/* The container only sets the width and gutters; each section lays out its own children. */
[data-slot='section-container'],
[data-slot='header-container'] {
  position: relative;
  width: 100%;
  min-width: 0;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: var(--gutter);
}
[data-slot='header-container'] {
  display: flex;
  gap: 16px;
}
[data-slot='section-title'] {
  font-size: 1.875rem;
  line-height: 2.25rem;
  text-wrap: balance;
}
[data-slot='section-description'] {
  font-size: 1.125rem;
  line-height: 1.625;
  color: var(--muted-foreground);
  text-wrap: balance;
}
/* Display headline of centered heroes and banners. */
.display-title {
  max-width: 56rem;
  font-size: 2.25rem;
  line-height: 1.1;
  text-wrap: balance;
}

/* The actions of a section intro, wrapping when they do not fit beside each other. */
.section-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
/* A section title set tight, as in Fulldev UI's call to action and content blocks. */
[data-slot='section-title'].tight-title {
  line-height: 1.1;
}
/* The display headline of split heroes: 36px, 48px from 640px. */
.hero-title {
  font-size: 2.25rem;
  line-height: 1.1;
  text-wrap: balance;
}
@media (min-width: 640px) {
  [data-slot='section-title'] {
    font-size: 2.25rem;
    line-height: 2.5rem;
  }
  .display-title,
  .hero-title {
    font-size: 3rem;
  }
}
@media (min-width: 1024px) {
  .display-title {
    font-size: 3.75rem;
  }
}
